import{_ as i,o as t,c as a,a2 as r}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"Enrichment, Caching & Resiliency","description":"","frontmatter":{},"headers":[],"relativePath":"harvester/enrichment-and-caching.md","filePath":"harvester/enrichment-and-caching.md","lastUpdated":null}'),n={name:"harvester/enrichment-and-caching.md"};function s(o,e,l,c,u,h){return t(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="enrichment-caching-resiliency" tabindex="-1">Enrichment, Caching &amp; Resiliency <a class="header-anchor" href="#enrichment-caching-resiliency" aria-label="Permalink to &quot;Enrichment, Caching &amp; Resiliency&quot;">​</a></h1><p>To rank search results accurately, Geomilli enriches raw OpenStreetMap places with global popularity metrics derived from <strong>Wikidata IDs</strong> and <strong>Wikipedia Pageviews statistics</strong>.</p><hr><h2 id="_1-enrichment-architecture" tabindex="-1">1. Enrichment Architecture <a class="header-anchor" href="#_1-enrichment-architecture" aria-label="Permalink to &quot;1. Enrichment Architecture&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Place[&quot;Transformed Place&lt;br/&gt;(wikidata=Q31)&quot;] --&gt; Cache{&quot;Check SQLite WAL&lt;br/&gt;Cache&quot;}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Cache --&gt;|&quot;Hit (TTL &lt; 30d)&quot;| Scored[&quot;Popularity Score Applied&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Cache --&gt;|&quot;Miss &amp; Online Enabled&quot;| Breaker{&quot;Circuit Breaker&lt;br/&gt;Tripped?&quot;}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Breaker --&gt;|&quot;No (&lt; 5 failures)&quot;| WikiAPI[&quot;Wikimedia Pageviews API&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Breaker --&gt;|&quot;Yes (Tripped)&quot;| Heuristic[&quot;Fallback Base Score Heuristic&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    WikiAPI --&gt;|&quot;200 OK / 404 Handled&quot;| SaveCache[&quot;Write to SQLite Cache&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    SaveCache --&gt; Scored</span></span></code></pre></div><hr><h2 id="_2-sqlite-wal-caching-rules" tabindex="-1">2. SQLite WAL Caching Rules <a class="header-anchor" href="#_2-sqlite-wal-caching-rules" aria-label="Permalink to &quot;2. SQLite WAL Caching Rules&quot;">​</a></h2><p>Because the enrichment stage runs across parallel worker goroutines, SQLite must be configured to prevent concurrency deadlocks (<code>SQLITE_BUSY</code>):</p><h3 id="architectural-constraints" tabindex="-1">Architectural Constraints: <a class="header-anchor" href="#architectural-constraints" aria-label="Permalink to &quot;Architectural Constraints:&quot;">​</a></h3><ul><li><strong>Write-Ahead Logging (WAL)</strong>: <code>PRAGMA journal_mode = WAL;</code> allows concurrent readers alongside a single writer.</li><li><strong>Busy Timeout</strong>: <code>PRAGMA busy_timeout = 5000;</code> ensures worker threads retry up to 5 seconds before failing on lock contention.</li><li><strong>Cache Retention</strong>: Cached records remain valid for <code>ENRICH_CACHE_TTL_DAYS</code> (default 30 days) to eliminate redundant outbound requests across re-indexing cycles.</li></ul><hr><h2 id="_3-network-resiliency-circuit-breaker" tabindex="-1">3. Network Resiliency &amp; Circuit Breaker <a class="header-anchor" href="#_3-network-resiliency-circuit-breaker" aria-label="Permalink to &quot;3. Network Resiliency &amp; Circuit Breaker&quot;">​</a></h2><p>Public Wikimedia APIs are subject to rate limiting and intermittent timeouts. Geomilli implements robust error handling:</p><ol><li><p><strong>Silent 404 Handling</strong>:</p><ul><li>Many OSM entities have Wikidata IDs without corresponding English or target Wikipedia articles.</li><li>The enrichment client treats HTTP <code>404 Not Found</code> silently by returning <code>(0, nil)</code>, preventing log spamming and pipeline delays.</li></ul></li><li><p><strong>Automatic Circuit Breaker</strong>:</p><ul><li>If <strong>5 consecutive network failures</strong> (e.g., DNS lookup errors, connection timeouts, HTTP 503) occur, the circuit breaker automatically trips.</li><li>Once tripped, the harvester disables online queries for the remainder of the stage and switches to <strong>offline heuristics</strong>, ensuring the ingestion pipeline finishes reliably even without an internet connection.</li></ul></li><li><p><strong>Rate Limiting</strong>:</p><ul><li>Outbound HTTP requests are throttled using a token bucket rate limiter governed by <code>ENRICH_QPS</code> (default: 3 requests/sec).</li></ul></li></ol><hr><h2 id="_4-offline-popularity-heuristics" tabindex="-1">4. Offline Popularity Heuristics <a class="header-anchor" href="#_4-offline-popularity-heuristics" aria-label="Permalink to &quot;4. Offline Popularity Heuristics&quot;">​</a></h2><p>When <code>ONLINE_ENRICH=false</code> or if the circuit breaker trips, Geomilli calculates a normalized <code>popularity_score</code> based on deterministic OSM indicators:</p><p>$$\\text{popularity_score} = \\text{base_score} + \\text{admin_bonus} + \\text{population_score} + \\text{tag_richness}$$</p><ul><li><strong>Base Class Score</strong>: Configured in <code>taxonomy.yaml</code> (e.g., Country: 100, City: 85, Airport: 95, Hotel: 65, Restaurant: 55).</li><li><strong>Admin Hierarchy Bonus</strong>: Capitals and administrative centers receive bonuses.</li><li><strong>Logarithmic Population</strong>: $\\log_{10}(\\text{population}) \\times 4$ for cities with <code>population=*</code> tags.</li><li><strong>Tag Richness</strong>: Entities possessing official websites, phone numbers, or opening hours receive confidence boosts.</li></ul>`,19)])])}const g=i(n,[["render",s]]);export{p as __pageData,g as default};
